#include <format>
#include <iostream>

class Registry {
 public:
  static Registry& instance() {
    static Registry registry;  // built the first time control reaches this line, not before main
    return registry;
  }
  void note() { ++seen_; }
  [[nodiscard]] int seen() const { return seen_; }

 private:
  Registry() { std::cout << "Registry() runs here, on first use\n"; }
  int seen_ = 0;
};

int main() {
  std::cout << "before the first call to instance()\n";
  Registry::instance().note();
  Registry::instance().note();
  std::cout << std::format("both calls returned the same object: {}\n",
                           &Registry::instance() == &Registry::instance());
  std::cout << std::format("seen() counts both calls: {}\n", Registry::instance().seen());
}

