#include <format>
#include <iostream>
#include <string>

class Config {
 public:
  static Config& instance() {
    std::cout << "instance() called\n";
    static Config config;  // built the first time control reaches this line, and never again
    return config;
  }
  [[nodiscard]] const std::string& robot_name() const { return robot_name_; }
  [[nodiscard]] static int built_count() { return built_count_; }

 private:
  Config() : robot_name_("bench-forward-01") { ++built_count_; }
  std::string robot_name_;
  static inline int built_count_ = 0;
};

int main() {
  std::cout << "before any call to instance()\n";
  std::cout << std::format("robot_name(): {}\n", Config::instance().robot_name());
  std::cout << std::format("robot_name(): {}\n", Config::instance().robot_name());
  std::cout << std::format("robot_name(): {}\n", Config::instance().robot_name());
  std::cout << std::format("constructor ran {} time(s)\n", Config::built_count());
  std::cout << std::format("both references are the same object: {}\n",
                           &Config::instance() == &Config::instance());
}

#include <csignal>
#include <format>
#include <iostream>

// A signal handler's signature is fixed by the operating system and takes no captured state,
// so the flag it sets has nowhere to live but namespace scope.
volatile std::sig_atomic_t g_stop = 0;

extern "C" void on_sigint(int) { g_stop = 1; }

int main() {
  std::signal(SIGINT, on_sigint);
  std::cout << std::format("before raise(SIGINT): g_stop = {}\n", g_stop);
  std::raise(SIGINT);
  std::cout << std::format("after raise(SIGINT):  g_stop = {}\n", g_stop);
}

#include <format>
#include <iostream>
#include <string>

class Config {
 public:
  static Config& instance() {
    static Config config;
    return config;
  }
  [[nodiscard]] const std::string& name() const { return name_; }

 private:
  Config() : name_("bench-forward-01, a name long enough to defeat the small string optimisation") {}
  std::string name_;
};

class Logger {
 public:
  static Logger& instance() {
    static Logger logger;
    return logger;
  }
  ~Logger() { std::cout << std::format("shutting down: {}\n", Config::instance().name()); }

 private:
  Logger() = default;
};

int main() {
  Logger::instance();  // first use: Logger's static is built first
  Config::instance();  // first use: Config's static is built second
  std::cout << "both singletons are alive here\n";
}
